/* Images used by the memorandum (letterhead logos and signatory seal), stored as data URIs.
   Kept as data URIs, not separate files, so PDF export can read them (a file:// image would block the canvas).
   Taken from UpdatedMemorandumTemplate.docx: left logo = the template's cropped picture, seal = the full picture. */
window.PNP = window.PNP || {};
PNP.ASSETS = {
  logoLeft: 'data:image/png;base64,',
  logoRight: 'data:image/png;base64,',
  seal: 'data:image/png;base64,'
};
